<template>
    <div class="incident-list">
        <div v-if="incidents.length === 0" class="no-incidents">No incidents found</div>
        <table v-else>
            <thead>
                <tr>
                    <th>Number</th>
                    <th>Description</th>
                    <th>State</th>
                    <th>Impact</th>
                    <th>Opened</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                <tr
                    v-for="incident in incidents"
                    :key="typeof incident.sys_id === 'object' ? incident.sys_id.value : incident.sys_id"
                >
                    <td>\{{ getDisplayValue(incident.number) }}</td>
                    <td>\{{ getDisplayValue(incident.short_description) }}</td>
                    <td>
                        <span class="state-badge" :class="getStateClass(incident.state)">
                            \{{ getDisplayValue(incident.state) }}
                        </span>
                    </td>
                    <td>
                        <span class="impact-badge" :class="getImpactClass(incident.impact)">
                            \{{ getDisplayValue(incident.impact) }}
                        </span>
                    </td>
                    <td>\{{ getDisplayValue(incident.opened_at) }}</td>
                    <td>
                        <div class="action-buttons">
                            <button class="edit-button" @click="onEdit(incident)">Edit</button>
                            <button class="delete-button" @click="handleDelete(incident)">Delete</button>
                        </div>
                    </td>
                </tr>
            </tbody>
        </table>
    </div>
</template>

<script setup lang="ts">
import './IncidentList.css'
import type { IncidentService } from '../services/IncidentService'
import type { Incident } from '../types'

const props = defineProps<{
    incidents: Incident[]
    onEdit: (incident: Incident) => void
    onRefresh: () => void
    service: IncidentService
}>()

import type { MaybeDisplayValue } from '../types'

const getDisplayValue = (field: MaybeDisplayValue<string>) =>
    typeof field === 'object' ? (field.display_value ?? field.value) : field

const getStateClass = (state: MaybeDisplayValue<string>) => {
    const value = typeof state === 'object' ? state.display_value : state
    switch (value) {
        case 'New':
            return 'state-new'
        case 'In Progress':
            return 'state-in-progress'
        case 'On Hold':
            return 'state-on-hold'
        case 'Resolved':
            return 'state-resolved'
        case 'Closed':
            return 'state-closed'
        default:
            return ''
    }
}

const getImpactClass = (impact: MaybeDisplayValue<string>) => {
    const value = typeof impact === 'object' ? impact.value : impact
    switch (value) {
        case '1':
            return 'impact-high'
        case '2':
            return 'impact-medium'
        case '3':
            return 'impact-low'
        default:
            return ''
    }
}

const handleDelete = async (incident: Incident) => {
    if (!confirm(`Are you sure you want to delete ${getDisplayValue(incident.number)}?`)) {
        return
    }
    try {
        const sysId = typeof incident.sys_id === 'object' ? incident.sys_id.value : incident.sys_id
        await props.service.delete(sysId)
        props.onRefresh()
    } catch (error: any) {
        console.error('Failed to delete incident:', error)
        alert('Failed to delete incident: ' + (error.message || 'Unknown error'))
    }
}
</script>
